require_once __DIR__ . '/../includes/config.php';
require_role(['student','host','coordinator']);db_required();$s=$pdo->prepare('SELECT ca.*,e.title FROM coordinator_applications ca JOIN events e ON e.id=ca.event_id WHERE ca.user_id=? ORDER BY ca.created_at DESC');$s->execute([current_user()['id']]);$rows=$s->fetchAll();$page_title='Coordinator Dashboard';require __DIR__.'/../includes/header.php';?><div class="container py-5"><div class="d-flex justify-content-between mb-4"><div><div class="section-kicker">Leadership</div><h2 class="fw-bold">Coordinator applications</h2></div><a href="/coordinator/apply.php" class="btn btn-primary rounded-pill">Apply for an event</a></div><div class="dash-card overflow-hidden"><div class="table-responsive"><table class="table mb-0 align-middle"><thead><tr><th>Event</th><th>Applied</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=date('d M Y',strtotime($r['created_at']))?></td><td><?=status_badge($r['status'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="3" class="empty">No coordinator applications yet.</td></tr><?php endif;?></tbody></table></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
